  function stamp(positions:Vec3[]){const p=objects?.presets.find(p=>p.key===placing?.key);if(!p||!['Inanimate','Decal'].includes(p.type))return;let id=nextId();const ops:EditOp[]=positions.flatMap(position=>{const currentId=id++;return[{kind:'prefab' as const,id:currentId,template:p.template,sourceId:p.sourceId,position},{kind:'transform' as const,id:currentId,rotation:nativeQuaternion(placing?.yaw??0,['x','y','z','w'].map(a=>Number(p.values['orientation.'+a]??(a==='w'?1:0))))}];});append(ops);setSelection(ops.filter(o=>o.kind==='prefab').map(o=>o.id));recordRecentPlacement(p.key);setStatus('已铺设 '+positions.length+' 个物件，可一步撤销');if(!placementPrefs.continuous)setPlacing(null);}
