  async function sampleObject(id:number){const entity=level?.entities.find(e=>e.id===id);if(!entity||!canModify(entity,display,layer))return;if(protectedCameraIds.has(id)){setStatus('请在原生区域面板复制相机对象');return;}if(!selectedLevel){setError('请进入小关卡后取样物件');return;}const capturedView=view,epoch=sampleEpoch.current;const sampleProfile=['Inanimate','Decal'].includes(entity.type)?'decoration':'mechanism';if(sampleProfile!==placementPrefs.profile)setPlacementPrefs(preference('placementProfile:'+sampleProfile,placementProfile(sampleProfile)));await task(async()=>{if(placementPrefs.associations==='material'){const fields=PROFILE_FIELDS[entity.type]??[],values=new Map(entity.nativeProperties?.map(p=>[p.field.name,p.value]));const candidates=objects?.presets.filter(p=>p.parsed&&p.type===entity.type&&p.mesh===entity.mesh)??[];const score=(p:ObjectPreset)=>fields.reduce((sum,key)=>sum+(JSON.stringify(p.signature[key]??p.values[key])===JSON.stringify(values.get(key))?1:0),0);const p=candidates.sort((a,b)=>score(b)-score(a))[0];if(!p)throw Error('找不到该物件对应的原生素材');choose(p);setPlacing({key:p.key,yaw:entity.yaw});}else{const bundle=await api.regionCapture(selectedLevel.project,{ids:[id],single:true,includeBackground:!display.categories.background.locked,associations:placementPrefs.associations});if(currentView.current!==capturedView||sampleEpoch.current!==epoch)return;setPlacing({key:uid('sample'),bundle,yaw:0});setStatus(bundle.warnings.length?'取样成功 · '+bundle.warnings.join('；'):'取样成功 · 新放置物件关联独立');}setTool('select');setSampling(false);setPlacementState(v=>({...v,continuous:true,associations:'independent'}));});}
